 func readCommittedMetadataFromCheckpointTree(checkpointTree *object.Tree, sessionIndex int) (Metadata, bool) {
 	sessionTree, treeErr := checkpointTree.Tree(strconv.Itoa(sessionIndex))
 	if treeErr != nil {
 		return Metadata{}, false
