 	if contentErr != nil {
 		return Metadata{}, false
 	}
 	var sessionMetadata Metadata
 	if err := json.Unmarshal([]byte(sessionContent), &sessionMetadata); err != nil {
 		return Metadata{}, false
 	}
 	return sessionMetadata, true
 }

