 	for i, cl := range cls {
 		out[i] = CodeLearning{
 			Path:    cl.Path,
 			Line:    cl.Line,
 			EndLine: cl.EndLine,
 			Finding: redact.String(cl.Finding),
 		}
 	}
 	return out
 }

