 15	// flakyReadStore wraps a real store and fails Read, leaving every other
 16	// operation intact. It stands in for a backend whose on-demand fetch is
 17	// temporarily unavailable.
 18	type flakyReadStore struct {
 19		PersistentStore
 20	
 21		readErr error
 22		writes  int
 23	}
 24	
 25	func (s *flakyReadStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 26		if s.readErr != nil {
 27			return nil, s.readErr
 28		}
 29		return s.PersistentStore.Read(ctx, checkpointID)
 30	}
 31	
 32	func (s *flakyReadStore) Write(ctx context.Context, req WriteRequest) error {
 33		s.writes++
 34		return s.PersistentStore.Write(ctx, req)
 35	}
