 15	// flakyReadStore wraps a real store and fails Read, leaving every other
 16	// operation intact. It stands in for a backend whose on-demand fetch is
 17	// temporarily unavailable.
 18	type flakyReadStore struct {
 19		PersistentStore
 20	
 21		readErr error
 22		writes  int
 23	}
 24	
 25	func (s *flakyReadStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 26		if s.readErr != nil {
 27			return nil, s.readErr
 28		}
 29		return s.PersistentStore.Read(ctx, checkpointID)
 30	}
 31	
 32	func (s *flakyReadStore) Write(ctx context.Context, req WriteRequest) error {
 33		s.writes++
 34		return s.PersistentStore.Write(ctx, req)
 35	}
 36	
 37	// countingStore records the write requests it receives so a test can assert
 38	// which backend a write reached.
 39	type countingStore struct {
 40		PersistentStore
 41	
 42		requests []WriteRequest
 43	}
 44	
 45	func (s *countingStore) Write(ctx context.Context, req WriteRequest) error {
 46		s.requests = append(s.requests, req)
 47		return s.PersistentStore.Write(ctx, req)
 48	}
 49	
 50	func reservedRoutingRequest(checkpointID id.CheckpointID) ReservedSession {
 51		return reservedRoutingRequestWith(checkpointID, "reserved-routing", "reserved transcript")
 52	}
 53	
 54	func reservedRoutingRequestWith(checkpointID id.CheckpointID, sessionID, transcript string) ReservedSession {
 55		return ReservedSession(WriteOptions{
 56			CheckpointID: checkpointID,
 57			SessionID:    sessionID,
 58			Strategy:     "manual-commit",
 59			Transcript:   redact.AlreadyRedacted([]byte(transcript)),
 60			AuthorName:   "Test",
 61			AuthorEmail:  "test@example.com",
 62		})
 63	}
 64	
 65	func batchRoutingRequest(checkpointID id.CheckpointID) BatchSessions {
 66		return BatchSessions{
 67			CheckpointID: checkpointID,
 68			Sessions: []ReservedSession{
 69				reservedRoutingRequest(checkpointID),
 70			},
 71			CommitTime:  batchTestTime,
 72			AuthorName:  "Test",
 73			AuthorEmail: "test@example.com",
 74		}
 75	}
