 77	// TestKindRoutingStore_ReservedSessionProbeFailurePublishesNowhere keeps a
 78	// transient read failure from publishing a one-sided migrated write.
 79	//
 80	// writeReservedRequest reads the read-preferred backend first, to find out
 81	// whether a migrated copy also needs updating. Treating that read's error as
 82	// non-fatal could leave the copy stale and read-preferred after recovery.
 83	func TestKindRoutingStore_ReservedSessionProbeFailurePublishesNowhere(t *testing.T) {
 84		t.Parallel()
 85		ctx := context.Background()
 86		checkpointID := id.MustCheckpointID("a1b2c3d4e5f6")
 87	
 88		_, repo, _ := newTestRepo(t)
 89		branch := NewGitStore(repo, DefaultV1Refs())
 90		refs := &flakyReadStore{PersistentStore: newGitRefsStore(repo), readErr: errors.New("refs fetch unavailable")}
 91	
 92		router := newKindRoutingStore(refs, branch, refs, BackendTypeGitRefs)
 93		err := router.Write(ctx, reservedRoutingRequest(checkpointID))
 94		require.ErrorContains(t, err, "probe read-preferred backend")
 95	
 96		summary, err := branch.Read(ctx, checkpointID)
 97		require.NoError(t, err)
 98		assert.Nil(t, summary, "a failed read-preferred probe must not publish the original-backend write")
 99	}
