101	func TestKindRoutingStore_ReservedSessionProbeFailurePreservesExistingCopies(t *testing.T) {
102		t.Parallel()
103		ctx := context.Background()
104		checkpointID := id.MustCheckpointID("b1b2c3d4e5f6")
105	
106		_, repo, _ := newTestRepo(t)
107		branch := NewGitStore(repo, DefaultV1Refs())
108		refsBase := newGitRefsStore(repo)
109		writeRoutingCheckpoint(t, branch, checkpointID, "old-session")
110		writeRoutingCheckpoint(t, refsBase, checkpointID, "old-session")
111		refs := &flakyReadStore{PersistentStore: refsBase, readErr: errors.New("refs fetch unavailable")}
112		router := newKindRoutingStore(refs, branch, refs, BackendTypeGitRefs)
113	
114		err := router.Write(ctx, reservedRoutingRequest(checkpointID))
115		require.ErrorContains(t, err, "probe read-preferred backend")
116	
117		refs.readErr = nil
118		branchContent, err := branch.ReadSessionContent(ctx, checkpointID, 0)
119		require.NoError(t, err)
120		assert.Contains(t, string(branchContent.Transcript), "old-session")
121		refsContent, err := refsBase.ReadSessionContent(ctx, checkpointID, 0)
122		require.NoError(t, err)
123		assert.Contains(t, string(refsContent.Transcript), "old-session")
124	
125		require.NoError(t, router.Write(ctx, reservedRoutingRequestWith(checkpointID, "old-session", "new transcript")))
126		summary, err := router.Read(ctx, checkpointID)
127		require.NoError(t, err)
128		require.NotNil(t, summary)
129		assert.Len(t, summary.Sessions, 1)
130		latestIndex := len(summary.Sessions) - 1
131		visibleContent, err := router.ReadSessionContent(ctx, checkpointID, latestIndex)
132		require.NoError(t, err)
133		assert.Contains(t, string(visibleContent.Transcript), "new transcript")
134	}
