 37	// countingStore records the write requests it receives so a test can assert
 38	// which backend a write reached.
 39	type countingStore struct {
 40		PersistentStore
 41	
 42		requests []WriteRequest
 43	}
 44	
 45	func (s *countingStore) Write(ctx context.Context, req WriteRequest) error {
 46		s.requests = append(s.requests, req)
 47		return s.PersistentStore.Write(ctx, req)
 48	}
