112		router := newKindRoutingStore(refs, branch, refs, BackendTypeGitRefs)
113	
114		err := router.Write(ctx, reservedRoutingRequest(checkpointID))
115		require.ErrorContains(t, err, "probe read-preferred backend")
116	
117		refs.readErr = nil
118		branchContent, err := branch.ReadSessionContent(ctx, checkpointID, 0)
119		require.NoError(t, err)
120		assert.Contains(t, string(branchContent.Transcript), "old-session")
121		refsContent, err := refsBase.ReadSessionContent(ctx, checkpointID, 0)
122		require.NoError(t, err)
