126		summary, err := router.Read(ctx, checkpointID)
127		require.NoError(t, err)
128		require.NotNil(t, summary)
129		assert.Len(t, summary.Sessions, 1)
130		latestIndex := len(summary.Sessions) - 1
131		visibleContent, err := router.ReadSessionContent(ctx, checkpointID, latestIndex)
132		require.NoError(t, err)
133		assert.Contains(t, string(visibleContent.Transcript), "new transcript")
