136	// TestKindRoutingStore_ReservedSessionFallsBackToWriterForUnknownPrimary keeps an
137	// unrecognised primary from being bypassed.
138	//
139	// writeReservedRequest compares the ID-derived backend against primaryType, so
140	// when primaryType is neither git-branch nor git-refs the comparison never
141	// matches and every reserved write skips s.writer — the configured primary and
142	// all its mirrors. readOrder already has an explicit default arm for this case;
143	// the write path should be at least as careful.
144	func TestKindRoutingStore_ReservedSessionFallsBackToWriterForUnknownPrimary(t *testing.T) {
