   620		return finalBatchSession{
   621			metadata:         metadata,
   622			hasReview:        metadata.Kind == checkpointKindAgentReview,
   623			hasInvestigation: metadata.Kind == checkpointKindAgentInvestigate,
   624			imported:         metadata.Kind == checkpointKindImported,
