 114	// Write dispatches on the request type, mirroring the git store's Write.
 115	func (s *Store) Write(_ context.Context, req cp.WriteRequest) error {
 116		s.mu.Lock()
 117		defer s.mu.Unlock()
 118	
 119		switch r := req.(type) {
 120		case cp.Session:
 121			return s.writeSingleSession(cp.WriteOptions(r))
 122		case cp.ReservedSession:
 123			return s.writeSingleSession(cp.WriteOptions(r))
 124		case cp.BatchSessions:
 125			return s.writeBatchSessions(r)
 126		case cp.SessionTranscript:
 127			return s.backfillTranscript(cp.UpdateOptions(r))
 128		case cp.SessionSummary:
 129			return s.writeSessionSummary(r)
 130		case cp.CheckpointAttribution:
 131			return s.writeAttribution(r)
 132		default:
 133			return fmt.Errorf("fsstore: unsupported write request %T", req)
 134		}
 135	}
