 183	func (s *Store) backfillTranscript(opts cp.UpdateOptions) error {
 184		sc, err := s.load(opts.CheckpointID)
 185		if err != nil {
 186			return err
 187		}
 188		if sc == nil {
 189			return fmt.Errorf("fsstore: cannot backfill transcript for unknown checkpoint %s", opts.CheckpointID)
 190		}
 191		idx := sessionIndexByID(sc.Sessions, opts.SessionID)
 192		if idx < 0 {
 193			return fmt.Errorf("fsstore: cannot backfill transcript for unknown session %q in %s", opts.SessionID, opts.CheckpointID)
 194		}
 195		// Replace semantics, but do not clobber sibling fields (matches the git
 196		// store's stop-time transcript backfill).
 197		sc.Sessions[idx].Transcript = opts.Transcript.Bytes()
 198		sc.Sessions[idx].Prompts = checkpoint.RedactedJoinedPrompts(opts.Prompts)
 199		if len(opts.SkillEvents) > 0 {
 200			sc.Sessions[idx].Metadata.SkillEvents = opts.SkillEvents
 201		}
 202		return s.save(sc)
 203	}
