 137	func (s *Store) writeSingleSession(opts cp.WriteOptions) error {
 138		req := cp.BatchSessions{
 139			CheckpointID: opts.CheckpointID,
 140			Sessions:     []cp.ReservedSession{cp.ReservedSession(opts)},
 141		}
 142		if err := s.writeBatchSessions(req); err != nil {
 143			return err
 144		}
 145		if opts.CombinedAttribution != nil {
 146			return s.writeAttribution(cp.CheckpointAttribution{
 147				CheckpointID: opts.CheckpointID,
 148				Attribution:  opts.CombinedAttribution,
 149			})
 150		}
