 154	func (s *Store) writeBatchSessions(req cp.BatchSessions) error {
 155		canonical, err := checkpoint.CanonicalizeBatchSessions(req)
 156		if err != nil {
 157			return fmt.Errorf("fsstore: validate batch: %w", err)
 158		}
 159		sc, err := s.load(canonical.CheckpointID)
 160		if err != nil {
 161			return err
 162		}
 163		if sc == nil {
 164			sc = &storedCheckpoint{Summary: cp.CheckpointSummary{CheckpointID: canonical.CheckpointID}}
 165		}
 166	
 167		for _, reserved := range canonical.Sessions {
 168			opts := cp.WriteOptions(reserved)
 169			session := storedSession{
 170				SessionID:  opts.SessionID,
 171				Metadata:   metadataFromWriteOptions(opts),
 172				Transcript: opts.Transcript.Bytes(),
 173				Prompts:    checkpoint.RedactedJoinedPrompts(opts.Prompts),
 174			}
 175			sc.Sessions = upsertSession(sc.Sessions, session)
 176			sc.Summary.HasReview = sc.Summary.HasReview || opts.HasReview
 177			sc.Summary.HasInvestigation = sc.Summary.HasInvestigation || opts.HasInvestigation
 178		}
 179		recomputeSummary(sc)
 180		return s.save(sc)
 181	}
