 205	func (s *Store) writeSessionSummary(r cp.SessionSummary) error {
 206		sc, err := s.load(r.CheckpointID)
 207		if err != nil {
 208			return err
 209		}
 210		if sc == nil || len(sc.Sessions) == 0 {
 211			return fmt.Errorf("fsstore: cannot set summary for unknown checkpoint %s", r.CheckpointID)
 212		}
 213		targetSessionID := r.SessionID
 214		if targetSessionID == "" {
 215			targetSessionID = sc.Sessions[len(sc.Sessions)-1].SessionID
 216		}
 217		idx := sessionIndexByID(sc.Sessions, targetSessionID)
 218		if idx < 0 {
 219			return &checkpoint.SessionNotFoundError{CheckpointID: r.CheckpointID, SessionID: targetSessionID}
 220		}
 221		sc.Sessions[idx].Metadata.Summary = checkpoint.RedactSummary(r.Summary)
 222		return s.save(sc)
 223	}
