333	// mergeFilesTouched merges multiple file lists into existing touched files, deduplicating.
334	// All paths are normalized to forward slashes for platform-agnostic storage.
335	func mergeFilesTouched(existing []string, fileLists ...[]string) []string {
336		seen := make(map[string]bool)
337		for _, f := range existing {
338			seen[filepath.ToSlash(f)] = true
339		}
340	
341		for _, list := range fileLists {
342			for _, f := range list {
343				seen[filepath.ToSlash(f)] = true
344			}
345		}
346	
347		result := make([]string, 0, len(seen))
348		for f := range seen {
349			result = append(result, f)
350		}
351	
352		// Sort for deterministic output
353		sort.Strings(result)
354		return result
355	}
