    25	// SaveStep saves a checkpoint to the shadow branch.
    26	// Uses checkpoint.EphemeralStore.Write with a checkpoint.Step request.
    27	func (s *ManualCommitStrategy) SaveStep(ctx context.Context, step StepContext) error {
    28		_, openRepoSpan := perf.Start(ctx, "open_repository")
    29		repo, err := OpenRepository(ctx)
    30		if err != nil {
    31			openRepoSpan.RecordError(err)
    32			openRepoSpan.End()
    33			return fmt.Errorf("failed to open git repository: %w", err)
    34		}
    35		defer repo.Close()
    36		openRepoSpan.End()
    37	
    38		sessionID := filepath.Base(step.MetadataDir)
    39	
    40		// Initialize the session if no state exists yet. Done outside
    41		// MutateSessionState because the helper bails with ErrStateNotFound on
    42		// missing state — initialization establishes the file the helper will
    43		// then mutate under lock.
    44		if err := s.ensureSessionInitialized(ctx, repo, sessionID, step.AgentType); err != nil {
    45			return err
    46		}
    47	
    48		mutErr := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
    49			_, migrateSpan := perf.Start(ctx, "migrate_shadow_branch")
    50			if _, _, err := s.migrateShadowBranchIfNeeded(ctx, repo, state); err != nil {
    51				migrateSpan.RecordError(err)
    52				migrateSpan.End()
    53				return fmt.Errorf("failed to check/migrate shadow branch: %w", err)
    54			}
    55			migrateSpan.End()
    56	
    57			store, err := s.getEphemeralStore(ctx, repo)
    58			if err != nil {
    59				return err
    60			}
    61	
    62			shadowBranchName := ""
    63			branchExisted := false
    64	
    65			var promptAttr PromptAttribution
    66			if state.PendingPromptAttribution != nil {
    67				promptAttr = *state.PendingPromptAttribution
    68				state.PendingPromptAttribution = nil
    69			} else {
    70				promptAttr = PromptAttribution{CheckpointNumber: state.StepCount + 1}
    71			}
    72	
    73			attrLogCtx := logging.WithComponent(ctx, "attribution")
    74			logging.Debug(attrLogCtx, "prompt attribution at checkpoint save",
    75				slog.Int("checkpoint_number", promptAttr.CheckpointNumber),
    76				slog.Int("user_added", promptAttr.UserLinesAdded),
    77				slog.Int("user_removed", promptAttr.UserLinesRemoved),
    78				slog.Int("agent_added", promptAttr.AgentLinesAdded),
    79				slog.Int("agent_removed", promptAttr.AgentLinesRemoved),
    80				slog.String("session_id", sessionID))
    81	
    82			_, writeCheckpointSpan := perf.Start(ctx, "write_temporary_checkpoint")
    83			isFirstCheckpointOfSession := state.StepCount == 0
    84			var result checkpoint.WriteEphemeralResult
    85			for attempt := range 2 {
    86				shadowBranchName = checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
    87				branchExisted = store.ShadowBranchExists(state.BaseCommit, state.WorktreeID)
    88				result, err = store.Write(ctx, checkpoint.Step{
    89					SessionID:         sessionID,
    90					BaseCommit:        state.BaseCommit,
    91					WorktreeID:        state.WorktreeID,
    92					ModifiedFiles:     step.ModifiedFiles,
    93					NewFiles:          step.NewFiles,
    94					DeletedFiles:      step.DeletedFiles,
    95					MetadataDir:       step.MetadataDir,
    96					MetadataDirAbs:    step.MetadataDirAbs,
    97					CommitMessage:     step.CommitMessage,
    98					AuthorName:        step.AuthorName,
    99					AuthorEmail:       step.AuthorEmail,
   100					IsFirstCheckpoint: isFirstCheckpointOfSession,
   101				})
   102				if !errors.Is(err, checkpoint.ErrShadowBranchMoved) || attempt == 1 {
   103					break
   104				}
   105				if _, _, migrateErr := s.migrateShadowBranchIfNeeded(ctx, repo, state); migrateErr != nil {
   106					err = fmt.Errorf("failed to retry shadow branch migration: %w", migrateErr)
   107					break
   108				}
   109			}
   110			writeCheckpointSpan.RecordError(err)
   111			writeCheckpointSpan.End()
   112			if err != nil {
   113				return fmt.Errorf("failed to write temporary checkpoint: %w", err)
   114			}
   115	
   116			if result.Skipped {
   117				logCtx := logging.WithComponent(ctx, "checkpoint")
   118				logging.Info(logCtx, "checkpoint skipped (no changes)",
   119					slog.String("strategy", "manual-commit"),
   120					slog.String("checkpoint_type", "session"),
   121					slog.Int("checkpoint_count", state.StepCount),
   122					slog.String("shadow_branch", shadowBranchName),
   123				)
   124				return ErrMutationSkip
   125			}
   126	
   127			// LastCheckpointID is intentionally NOT cleared here. It is set during
   128			// condensation and used by handleAmendCommitMsg to restore checkpoint
   129			// trailers on amend operations.
   130			state.StepCount++
   131			state.PromptAttributions = append(state.PromptAttributions, promptAttr)
   132			state.FilesTouched = mergeFilesTouched(state.FilesTouched, step.ModifiedFiles, step.NewFiles, step.DeletedFiles)
   133			if state.StepCount == 1 {
   134				state.TranscriptIdentifierAtStart = step.StepTranscriptIdentifier
   135			}
   136			if step.TokenUsage != nil {
   137				state.TokenUsage = accumulateTokenUsage(state.TokenUsage, step.TokenUsage)
   138				state.CheckpointTokenUsage = accumulateTokenUsage(state.CheckpointTokenUsage, step.TokenUsage)
   139				// step.TokenUsage.SubagentTokens is a cumulative-since-session-start
   140				// snapshot (agent IDs are discovered from the full transcript and each
   141				// subagent's own transcript is re-read from its start on every call —
   142				// see CalculateTotalTokenUsage in the claudecode/factoryaidroid
   143				// packages), not a per-step delta like the rest of TokenUsage.
   144				// accumulateTokenUsage already replaces (rather than adds) the
   145				// SubagentTokens field for that reason, so state.TokenUsage ends up
   146				// correctly holding the latest cumulative total. CheckpointTokenUsage
   147				// additionally needs rescoping to "since last condensation" by
   148				// subtracting the baseline captured at the last reset, otherwise the
   149				// full cumulative subagent total would be reported again at every
   150				// checkpoint instead of just this checkpoint's share.
   151				//
   152				// Derive the checkpoint delta FRESH each call from the session-wide
   153				// cumulative (state.TokenUsage.SubagentTokens) minus the baseline —
   154				// do NOT mutate CheckpointTokenUsage.SubagentTokens in place. A later
   155				// step in the same window can carry step.TokenUsage != nil but
   156				// SubagentTokens == nil (the subagent transcript was cleaned up, so
   157				// CalculateTotalTokenUsage returned APICallCount==0 and left it nil);
   158				// accumulateTokenUsage then leaves CheckpointTokenUsage.SubagentTokens
   159				// at its already-rescoped value, and re-subtracting the baseline from
   160				// that would double-subtract and (via clampSubtract) shrink or zero a
   161				// real subagent total. Recomputing from the session-wide cumulative
   162				// is idempotent regardless of whether this step carried a snapshot.
   163				if state.CheckpointTokenUsage != nil {
   164					state.CheckpointTokenUsage.SubagentTokens = types.SubtractTokenUsage(
   165						state.TokenUsage.SubagentTokens, state.SubagentTokensBaseline)
   166				}
   167			}
   168	
   169			if !branchExisted {
   170				logging.Info(logging.WithComponent(ctx, "checkpoint"), "created shadow branch and committed changes",
   171					slog.String("shadow_branch", shadowBranchName))
   172			} else {
   173				logging.Info(logging.WithComponent(ctx, "checkpoint"), "committed changes to shadow branch",
   174					slog.String("shadow_branch", shadowBranchName))
   175			}
   176	
   177			logCtx := logging.WithComponent(ctx, "checkpoint")
   178			logging.Info(logCtx, "checkpoint saved",
   179				slog.String("strategy", "manual-commit"),
   180				slog.String("checkpoint_type", "session"),
   181				slog.Int("checkpoint_count", state.StepCount),
   182				slog.Int("modified_files", len(step.ModifiedFiles)),
   183				slog.Int("new_files", len(step.NewFiles)),
   184				slog.Int("deleted_files", len(step.DeletedFiles)),
   185				slog.String("shadow_branch", shadowBranchName),
   186				slog.Bool("branch_created", !branchExisted),
   187			)
   188			return nil
   189		})
   190		if errors.Is(mutErr, ErrStateNotFound) {
   191			return nil
   192		}
   193		return mutErr
   194	}
