   302					slog.String("shadow_branch", shadowBranchName))
   303			} else {
   304				logging.Info(logging.WithComponent(ctx, "checkpoint"), "committed task checkpoint to shadow branch",
   305					slog.String("shadow_branch", shadowBranchName))
   306			}
   307	
   308			logCtx := logging.WithComponent(ctx, "checkpoint")
   309			attrs := []any{
   310				slog.String("strategy", "manual-commit"),
   311				slog.String("checkpoint_type", "task"),
   312				slog.String("checkpoint_uuid", step.CheckpointUUID),
   313				slog.String("tool_use_id", step.ToolUseID),
   314				slog.String("subagent_type", step.SubagentType),
   315				slog.Int("modified_files", len(step.ModifiedFiles)),
