   182	// buildCheckpointSubtree builds the checkpoint subtree object from entries keyed
   183	// under basePath, stripping the prefix so the subtree is rooted at the checkpoint
   184	// directory. With basePath "" the entries are already root-relative.
   185	func (s *treeWriter) buildCheckpointSubtree(ctx context.Context, entries map[string]object.TreeEntry, basePath string) (plumbing.Hash, error) {
   186		relEntries := entries
   187		if basePath != "" {
   188			relEntries = make(map[string]object.TreeEntry, len(entries))
   189			for path, entry := range entries {
   190				relPath := strings.TrimPrefix(path, basePath)
   191				if relPath == path {
   192					continue // Entry doesn't have the expected prefix
   193				}
   194				relEntries[relPath] = entry
   195			}
   196		}
   197		subtree, err := BuildTreeFromEntries(ctx, s.repo, relEntries)
   198		if err != nil {
   199			return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
   200		}
   201		return subtree, nil
   202	}
   203	
   204	// spliceCheckpointSubtree installs a prebuilt checkpoint subtree at the shard
   205	// location in the v1 root tree using O(depth) tree surgery, returning the new
   206	// root tree hash. The v1 branch always shards on the first two ID characters.
   207	func (s *GitStore) spliceCheckpointSubtree(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, checkpointSubtree plumbing.Hash) (plumbing.Hash, error) {
   208		shardPrefix := string(checkpointID[:2])
   209		shardSuffix := string(checkpointID[2:])
   210		return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
   211			{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointSubtree},
   212		}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
   213	}
   214	
   215	// applySessionWrite applies a Session write to a checkpoint's current subtree
   216	// and returns the new checkpoint subtree hash. It is backing-independent: the
   217	// v1-branch store passes the sharded basePath and the per-checkpoint-ref
   218	// store passes "".
   219	func (s *treeWriter) applySessionWrite(ctx context.Context, opts WriteOptions, existing *object.Tree, basePath string) (plumbing.Hash, error) {
   220		entries, err := s.flattenExisting(existing, basePath)
   221		if err != nil {
   222			return plumbing.ZeroHash, err
   223		}
   224	
   225		if err := s.writeTaskRecordEntries(opts, basePath, entries); err != nil {
   226			return plumbing.ZeroHash, err
   227		}
   228	
   229		if err := s.writeStandardCheckpointEntries(ctx, opts, basePath, entries); err != nil {
   230			return plumbing.ZeroHash, err
   231		}
   232	
   233		return s.buildCheckpointSubtree(ctx, entries, basePath)
   234	}
   235	
   236	// applyAttributionBackfill rewrites the checkpoint root summary's combined
   237	// attribution on the checkpoint's current subtree, returning the new subtree
   238	// hash. Returns ErrCheckpointNotFound when the checkpoint has no root summary.
   239	func (s *treeWriter) applyAttributionBackfill(ctx context.Context, existing *object.Tree, basePath string, combinedAttribution *Attribution) (plumbing.Hash, error) {
   240		entries, err := s.flattenExisting(existing, basePath)
   241		if err != nil {
   242			return plumbing.ZeroHash, err
   243		}
   244	
   245		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
   246		entry, exists := entries[rootMetadataPath]
   247		if !exists {
   248			return plumbing.ZeroHash, ErrCheckpointNotFound
   249		}
   250	
   251		summary, err := s.readSummaryFromBlob(entry.Hash)
   252		if err != nil {
   253			return plumbing.ZeroHash, fmt.Errorf("failed to read checkpoint summary: %w", err)
   254		}
   255		summary.CombinedAttribution = combinedAttribution
   256	
   257		metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
   258		if err != nil {
   259			return plumbing.ZeroHash, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
   260		}
   261		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   262		if err != nil {
   263			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
   264		}
   265		entries[rootMetadataPath] = object.TreeEntry{
   266			Name: rootMetadataPath,
   267			Mode: filemode.Regular,
   268			Hash: metadataHash,
   269		}
   270	
   271		return s.buildCheckpointSubtree(ctx, entries, basePath)
   272	}
   273	
   274	// applySummaryBackfill rewrites the latest session's summary on the checkpoint's
   275	// current subtree, returning the new subtree hash and that session's ID (for the
   276	// commit message). Returns ErrCheckpointNotFound when the checkpoint has no root
   277	// summary.
   278	func (s *treeWriter) applySummaryBackfill(ctx context.Context, existing *object.Tree, basePath string, summary *Summary) (plumbing.Hash, string, error) {
   279		entries, err := s.flattenExisting(existing, basePath)
   280		if err != nil {
   281			return plumbing.ZeroHash, "", err
   282		}
   283	
   284		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
   285		entry, exists := entries[rootMetadataPath]
   286		if !exists {
   287			return plumbing.ZeroHash, "", ErrCheckpointNotFound
   288		}
   289	
   290		checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
   291		if err != nil {
   292			return plumbing.ZeroHash, "", fmt.Errorf("failed to read checkpoint summary: %w", err)
   293		}
   294	
   295		// Find the latest session's metadata path (0-based indexing)
   296		latestIndex := len(checkpointSummary.Sessions) - 1
   297		sessionMetadataPath := checkpointSubtreePath(basePath, strconv.Itoa(latestIndex), paths.MetadataFileName)
   298		sessionEntry, exists := entries[sessionMetadataPath]
   299		if !exists {
   300			return plumbing.ZeroHash, "", fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
   301		}
   302	
   303		existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
   304		if err != nil {
   305			return plumbing.ZeroHash, "", fmt.Errorf("failed to read session metadata: %w", err)
   306		}
   307	
   308		existingMetadata.Summary = RedactSummary(summary)
   309	
   310		metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
   311		if err != nil {
   312			return plumbing.ZeroHash, "", fmt.Errorf("failed to marshal metadata: %w", err)
   313		}
   314		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   315		if err != nil {
   316			return plumbing.ZeroHash, "", fmt.Errorf("failed to create metadata blob: %w", err)
   317		}
   318		entries[sessionMetadataPath] = object.TreeEntry{
   319			Name: sessionMetadataPath,
   320			Mode: filemode.Regular,
   321			Hash: metadataHash,
   322		}
   323	
   324		subtree, err := s.buildCheckpointSubtree(ctx, entries, basePath)
   325		if err != nil {
   326			return plumbing.ZeroHash, "", err
   327		}
   328		return subtree, existingMetadata.SessionID, nil
   329	}
