  86	func synchronizedFirstCAS(t *testing.T) (context.Context, context.Context, func()) {
  87		t.Helper()
  88		ready := make(chan struct{}, 2)
  89		proceed := make(chan struct{})
  90		makeContext := func() context.Context {
  91			var once sync.Once
  92			return withBeforeRefCAS(t.Context(), func() {
  93				once.Do(func() {
  94					ready <- struct{}{}
  95					<-proceed
  96				})
  97			})
  98		}
  99		release := func() {
 100			t.Helper()
 101			<-ready
 102			<-ready
 103			close(proceed)
 104		}
 105		return makeContext(), makeContext(), release
 106	}
