1053		condensedTelemetry := newCommitCondensedEmitter(worktreePath, newHead)
1054	
1055		loopCtx, processSessionsLoop := perf.StartLoop(ctx, "process_sessions")
1056		for _, sess := range sessions {
1057			if sess.FullyCondensed && sess.Phase == session.PhaseEnded {
1058				continue
1059			}
1060			sessionID := sess.SessionID
1061			iterCtx, iterSpan := processSessionsLoop.Iteration(loopCtx)
1062			var newSkillEvents []agent.SkillEvent
1063			var condensedSignal *commitCondensedSignal
1064			mutErr := MutateSessionStateOnSaved(iterCtx, sessionID, func(state *SessionState) error {
1065				newSkillEvents, condensedSignal = s.postCommitProcessSessionLocked(iterCtx, repo, state, &transitionCtx, checkpointID,
1066					head, commit, newHead, worktreePath, headTree, parentTree,
1067					committedFileSet, shadowBranchesToDelete, uncondensedActiveOnBranch, allAgentFiles,
1068					sessionsWithCommittedFiles, condensedTelemetry)
1069				return nil
1070			}, func() {
1071				EmitSkillInvocationTelemetry(iterCtx, newSkillEvents)
1072				condensedTelemetry.emit(iterCtx, condensedSignal)
1073			})
1074			if mutErr != nil && !errors.Is(mutErr, ErrStateNotFound) {
1075				logging.Warn(logCtx, "post-commit: session mutation failed",
1076					slog.String("session_id", sessionID),
1077					slog.String("error", mutErr.Error()))
1078			}
1079			iterSpan.End()
1080		}
1081		processSessionsLoop.End()
1082	
1083		if err := s.updateCombinedAttributionForCheckpoint(ctx, repo, checkpointID, headTree, parentTree, worktreePath); err != nil {
1084			logging.Warn(logCtx, "failed to update combined checkpoint attribution",
1085				slog.String("checkpoint_id", checkpointID.String()),
1086				slog.String("error", err.Error()))
1087		}
1088	
1089		// Clean up shadow branches — only delete when ALL sessions on the branch are non-active
1090		// or were condensed during this PostCommit.
1091		_, cleanupBranchesSpan := perf.Start(ctx, "cleanup_shadow_branches")
1092		for shadowBranchName := range shadowBranchesToDelete {
1093			if uncondensedActiveOnBranch[shadowBranchName] {
1094				logging.Debug(logCtx, "post-commit: preserving shadow branch (active session exists)",
1095					slog.String("shadow_branch", shadowBranchName),
1096				)
1097				continue
