  12	func TestGitStore_ConcurrentWritesPreserveBothCheckpoints(t *testing.T) {
  13		t.Parallel()
  14		repo, _ := setupBranchTestRepo(t)
  15		store := NewGitStore(repo, DefaultV1Refs())
  16		if err := store.ensureSessionsBranch(t.Context()); err != nil {
  17			t.Fatalf("ensure sessions branch: %v", err)
  18		}
  19	
  20		ctxA, ctxB, release := synchronizedFirstCAS(t)
  21		errCh := make(chan error, 2)
  22		go func() {
  23			errCh <- store.Write(ctxA, concurrentSession(id.MustCheckpointID("a1b2c3d4e5f6"), "session-a"))
  24		}()
  25		go func() {
  26			errCh <- store.Write(ctxB, concurrentSession(id.MustCheckpointID("b1c2d3e4f5a6"), "session-b"))
  27		}()
  28		release()
  29		for range 2 {
  30			if err := <-errCh; err != nil {
  31				t.Fatalf("concurrent write: %v", err)
