 131	func TestRunRefTransaction_RebuildsAfterConflict(t *testing.T) {
 132		t.Parallel()
 133		dir := t.TempDir()
 134		testutil.InitRepo(t, dir)
 135		testutil.WriteFile(t, dir, "initial.txt", "initial")
 136		testutil.GitAdd(t, dir, "initial.txt")
 137		testutil.GitCommit(t, dir, "initial")
 138		repo, err := gitrepo.OpenPath(dir)
 139		if err != nil {
 140			t.Fatalf("open repo: %v", err)
 141		}
 142		defer repo.Close()
 143	
 144		head, err := repo.Head()
 145		if err != nil {
 146			t.Fatalf("read HEAD: %v", err)
 147		}
 148		refName := plumbing.ReferenceName("refs/entire/checkpoints/01/retry")
 149		calls := 0
 150		got, err := RunRefTransaction(t.Context(), repo, refName, func(current plumbing.Hash) (plumbing.Hash, bool, error) {
 151			calls++
 152			if calls == 1 {
 153				if err := CompareAndSwapRef(t.Context(), repo, refName, head.Hash(), plumbing.ZeroHash); err != nil {
 154					return plumbing.ZeroHash, false, err
 155				}
 156				return head.Hash(), true, nil
 157			}
 158			if current != head.Hash() {
 159				t.Fatalf("retry current = %s, want %s", current, head.Hash())
 160			}
 161			return current, false, nil
 162		})
 163		if err != nil {
 164			t.Fatalf("RunRefTransaction: %v", err)
 165		}
 166		if got != head.Hash() {
 167			t.Fatalf("result = %s, want %s", got, head.Hash())
 168		}
 169		if calls != 2 {
 170			t.Fatalf("mutation calls = %d, want 2", calls)
 171		}
 172	}
