1119	// updateCombinedAttributionForCheckpoint computes holistic attribution across all sessions.
1120	// Instead of summing per-session numbers (which inflates totals because each session
1121	// independently counts the full commit), this diffs parent→HEAD once and classifies
1122	// lines as agent or human based on the union of all sessions' files_touched.
1123	func (s *ManualCommitStrategy) updateCombinedAttributionForCheckpoint(
1124		ctx context.Context,
1125		repo *git.Repository,
1126		checkpointID id.CheckpointID,
1127		headTree, parentTree *object.Tree,
1128		repoDir string,
1129	) error {
1130		logCtx := logging.WithComponent(ctx, "attribution")
1131		// The hook store envelope (see hookCheckpointStoreOptions): the attribution
1132		// backfill's absence probe fetches a ref that exists remotely but not
1133		// locally, and on a partial clone the checkpoint's own blobs need fetching
1134		// too. Bounded budgets keep a dead network from stalling the post-commit
1135		// hook: the ref store memoizes a failed ref fetch (gitRefsStore.fetchFailure)
1136		// and hookBlobFetcher memoizes an exhausted blob fetch, so the two paths are
1137		// bounded independently.
1138		stores, err := checkpoint.Open(ctx, repo, s.hookCheckpointStoreOptions(ctx))
1139		if err != nil {
1140			return fmt.Errorf("open checkpoint store: %w", err)
1141		}
1142		store := stores.Persistent
1143	
1144		summary, err := store.Read(ctx, checkpointID)
1145		if err != nil {
1146			return fmt.Errorf("reading checkpoint summary: %w", err)
1147		}
1148		if summary == nil || len(summary.Sessions) <= 1 {
1149			return nil
1150		}
1151	
1152		// Collect union of files_touched from sessions that had real checkpoints (SaveStep ran).
1153		// Sessions with no SaveStep steps (e.g., commit-only sessions) use a fallback that
1154		// includes ALL committed files, which would incorrectly classify human-created files as agent work.
1155		// Gate on SaveStepCount (the honest "SaveStep ran" signal), not CheckpointsCount —
1156		// CheckpointsCount is now a prompt count floored at 1, so it's no longer 0 for these sessions.
1157		// Old metadata lacks SaveStepCount → 0 → conservatively skipped, matching prior behavior.
1158		agentFiles := make(map[string]struct{})
1159		for i := range len(summary.Sessions) {
1160			metadata, readErr := store.ReadSessionMetadata(ctx, checkpointID, i)
1161			if readErr != nil || metadata == nil {
1162				continue
1163			}
1164			if metadata.SaveStepCount == 0 {
1165				continue // Skip sessions that used the filesTouched fallback
1166			}
1167			for _, f := range metadata.FilesTouched {
1168				agentFiles[f] = struct{}{}
1169			}
1170		}
