399	// writeTaskRecordEntry writes one TaskPayload's agent-<agent-id>.jsonl (when
400	// its transcript is available) and task.json into entries.
401	func (s *treeWriter) writeTaskRecordEntry(task TaskPayload, basePath string, entries map[string]object.TreeEntry) error {
402		taskDir := checkpointSubtreePath(basePath, "tasks", task.ToolUseID)
403	
404		if task.Transcript.Len() > 0 {
405			agentBlobHash, err := CreateBlobFromContent(s.repo, task.Transcript.Bytes())
406			if err != nil {
407				return fmt.Errorf("failed to create task transcript blob: %w", err)
408			}
409			agentPath := checkpointSubtreePath(taskDir, "agent-"+task.AgentID+".jsonl")
410			entries[agentPath] = object.TreeEntry{
411				Name: agentPath,
412				Mode: filemode.Regular,
413				Hash: agentBlobHash,
414			}
415		}
416	
417		// The description is the agent's free text for the Task call (it can carry
418		// whatever the prompt carried), and task.json is pushed with the checkpoint,
419		// so it goes through the same redactor as the summary fields — see
420		// RedactSummary. The transcript beside it arrives pre-redacted.
421		metadata := taskRecordMetadata{
422			ToolUseID:                   task.ToolUseID,
423			AgentID:                     task.AgentID,
424			SubagentType:                task.SubagentType,
425			TaskDescription:             redact.String(task.TaskDescription),
426			Files:                       task.Files,
427			TokenUsage:                  task.TokenUsage,
428			StartedAt:                   task.StartedAt,
429			CompletedAt:                 task.CompletedAt,
430			TranscriptUnavailableReason: task.TranscriptUnavailableReason,
500						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree entire/checkpoints/v1 %s/`",
501						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, opts.CheckpointID.Path(),
502					)
503				}
504			}
505		}
506	
507		// Write session files to numbered subdirectory
508		sessionDir := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex))
509		sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionDir, entries)
510		if err != nil {
511			return err
512		}
513	
514		// Copy additional metadata files from directory if specified (to session subdirectory)
515		if opts.MetadataDir != "" {
516			if err := s.copyMetadataDir(ctx, opts.MetadataDir, sessionDir, entries); err != nil {
517				return fmt.Errorf("failed to copy metadata directory: %w", err)
518			}
519		}
520	
521		// Build the sessions array
522		var sessions []SessionFilePaths
523		if existingSummary != nil {
524			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
525			copy(sessions, existingSummary.Sessions)
526		} else {
527			sessions = make([]SessionFilePaths, 1)
528		}
529		sessions[sessionIndex] = sessionFilePaths
530	
531		// Tripwire: an unreproduced production report had session 0 silently
532		// replaced with a different sessionID's data. The symptom was
533		// findSessionIndex returning 0 when it should have returned N
534		// (append). That happens if existingSummary is nil — yet the
535		// on-disk tree clearly had session 0's metadata. If we're writing
536		// at sessionIndex=0 while entries has pre-existing session-0
537		// metadata with a DIFFERENT sessionID, that's the exact bug shape.
538		// Loud WARN so we get a log trace instead of only the symptom.
539		if sessionIndex == 0 {
540			path := checkpointSubtreePath(basePath, "0", paths.MetadataFileName)
541			if entry, exists := entries[path]; exists {
542				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
543					logging.Warn(ctx, "checkpoint write overwrites session 0 with a different sessionID — potential overwrite regression",
544						slog.String("checkpoint_id", opts.CheckpointID.String()),
545						slog.String("existing_session_id", existingMeta.SessionID),
546						slog.String("write_session_id", opts.SessionID),
547						slog.Bool("existing_summary_nil", existingSummary == nil))
548				}
549			}
550		}
551	
552		// Update root metadata.json with CheckpointSummary
553		return s.writeCheckpointSummary(opts, basePath, entries, sessions)
554	}
