160	// applyAttributionBackfill rewrites the checkpoint root summary's combined
161	// attribution on the checkpoint's current subtree, returning the new subtree
162	// hash. Returns ErrCheckpointNotFound when the checkpoint has no root summary.
163	func (s *treeWriter) applyAttributionBackfill(ctx context.Context, existing *object.Tree, basePath string, combinedAttribution *Attribution) (plumbing.Hash, error) {
164		entries, err := s.flattenExisting(existing, basePath)
165		if err != nil {
166			return plumbing.ZeroHash, err
167		}
168	
169		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
170		entry, exists := entries[rootMetadataPath]
171		if !exists {
172			return plumbing.ZeroHash, ErrCheckpointNotFound
173		}
174	
175		summary, err := s.readSummaryFromBlob(entry.Hash)
176		if err != nil {
177			return plumbing.ZeroHash, fmt.Errorf("failed to read checkpoint summary: %w", err)
178		}
179		summary.CombinedAttribution = combinedAttribution
180	
181		metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
182		if err != nil {
183			return plumbing.ZeroHash, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
184		}
185		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
186		if err != nil {
187			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
188		}
189		entries[rootMetadataPath] = object.TreeEntry{
190			Name: rootMetadataPath,
191			Mode: filemode.Regular,
192			Hash: metadataHash,
193		}
194	
195		return s.buildCheckpointSubtree(ctx, entries, basePath)
196	}
