522		var sessions []SessionFilePaths
523		if existingSummary != nil {
524			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
525			copy(sessions, existingSummary.Sessions)
526		} else {
527			sessions = make([]SessionFilePaths, 1)
528		}
529		sessions[sessionIndex] = sessionFilePaths
530	
531		// Tripwire: an unreproduced production report had session 0 silently
532		// replaced with a different sessionID's data. The symptom was
533		// findSessionIndex returning 0 when it should have returned N
534		// (append). That happens if existingSummary is nil — yet the
535		// on-disk tree clearly had session 0's metadata. If we're writing
536		// at sessionIndex=0 while entries has pre-existing session-0
537		// metadata with a DIFFERENT sessionID, that's the exact bug shape.
538		// Loud WARN so we get a log trace instead of only the symptom.
539		if sessionIndex == 0 {
540			path := checkpointSubtreePath(basePath, "0", paths.MetadataFileName)
541			if entry, exists := entries[path]; exists {
542				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
543					logging.Warn(ctx, "checkpoint write overwrites session 0 with a different sessionID — potential overwrite regression",
544						slog.String("checkpoint_id", opts.CheckpointID.String()),
545						slog.String("existing_session_id", existingMeta.SessionID),
546						slog.String("write_session_id", opts.SessionID),
547						slog.Bool("existing_summary_nil", existingSummary == nil))
548				}
549			}
550		}
551	
552		// Update root metadata.json with CheckpointSummary
553		return s.writeCheckpointSummary(opts, basePath, entries, sessions)
554	}
