676	// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
677	// sessions is the complete sessions array (already built by the caller).
678	func (s *treeWriter) writeCheckpointSummary(opts WriteOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
679		checkpointsCount, filesTouched, tokenUsage, err := s.reaggregateFromEntries(basePath, len(sessions), entries)
680		if err != nil {
681			return fmt.Errorf("failed to aggregate session stats: %w", err)
682		}
683	
684		combinedAttribution := opts.CombinedAttribution
685		hasReview := opts.HasReview
686		hasInvestigation := opts.HasInvestigation
687		// imported is the umbrella flag: true when any session in this checkpoint
688		// was imported. The session package imports checkpoint, so its constant is
689		// deliberately mirrored here.
690		imported := opts.Kind == checkpointKindImported
691		commitSHA := opts.CommitSHA
692		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
693		if entry, exists := entries[rootMetadataPath]; exists {
694			existingSummary, readErr := s.readSummaryFromBlob(entry.Hash)
695			if readErr == nil {
696				if combinedAttribution == nil {
697					combinedAttribution = existingSummary.CombinedAttribution
698				}
699				if !hasReview {
700					hasReview = existingSummary.HasReview
701				}
702				if !hasInvestigation {
703					hasInvestigation = existingSummary.HasInvestigation
704				}
705				if !imported {
706					imported = existingSummary.Imported
707				}
708				// A later write to the same checkpoint (e.g. a review session
709				// attached to it) carries no CommitSHA; the imported anchor
710				// must survive that rewrite rather than be cleared.
711				if commitSHA == "" {
712					commitSHA = existingSummary.CommitSHA
713				}
714			}
715		}
716	
717		summary := CheckpointSummary{
718			CheckpointID:        opts.CheckpointID,
719			CLIVersion:          versioninfo.Version,
720			Strategy:            opts.Strategy,
721			Branch:              opts.Branch,
722			CommitSHA:           commitSHA,
723			CheckpointsCount:    checkpointsCount,
724			FilesTouched:        filesTouched,
725			Sessions:            sessions,
726			TokenUsage:          tokenUsage,
727			CombinedAttribution: combinedAttribution,
728			HasReview:           hasReview,
729			HasInvestigation:    hasInvestigation,
730			Imported:            imported,
731		}
732	
733		metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
734		if err != nil {
735			return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
736		}
737		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
738		if err != nil {
739			return err
740		}
741		entries[rootMetadataPath] = object.TreeEntry{
742			Name: rootMetadataPath,
743			Mode: filemode.Regular,
744			Hash: metadataHash,
745		}
746		return nil
747	}
