 18	// TestSeam_GitRefsPrimaryWithGitBranchMirror drives the branch->refs rollout
 19	// topology through checkpoint.Open: a git-refs primary with a git-branch mirror.
 20	// It writes all six WriteRequest variants and asserts reads resolve from the
 21	// git-refs primary while the git-branch mirror (the v1 branch) independently
 22	// received every write.
 23	//
 24	// Not parallel: uses t.Chdir so settings + ref resolution target the test repo.
 25	func TestSeam_GitRefsPrimaryWithGitBranchMirror(t *testing.T) {
 26		dir := t.TempDir()
 27		testutil.InitRepo(t, dir)
 28		testutil.WriteFile(t, dir, "README.md", "# test")
 29		testutil.GitAdd(t, dir, "README.md")
 30		testutil.GitCommit(t, dir, "init")
 31	
 32		body := `{"enabled": true, "checkpoints": {"primary": {"type": "git-refs"}, "mirrors": [{"type": "git-branch"}]}}`
 33		require.NoError(t, os.MkdirAll(filepath.Join(dir, ".entire"), 0o755))
 34		require.NoError(t, os.WriteFile(filepath.Join(dir, ".entire", "settings.json"), []byte(body), 0o644))
 35		t.Chdir(dir)
 36	
 37		repo, err := git.PlainOpen(dir)
 38		require.NoError(t, err)
 39		stores, err := Open(context.Background(), repo, OpenOptions{})
 40		require.NoError(t, err)
 41	
 42		ctx := context.Background()
 43		cid := id.MustCheckpointID("a1b2c3d4e5f6")
 44		reservedCID := id.MustCheckpointID("01ARZ3NDEKTSV4RRFFQ69G5FAV")
 45		batchCID := id.MustCheckpointID("01ARZ3NDEKTSV4RRFFQ69G5FAW")
 46		const sessionID = "sess-1"
 47	
 48		require.NoError(t, stores.Persistent.Write(ctx, Session{
 49			CheckpointID: cid, SessionID: sessionID, Strategy: "manual-commit",
 50			Transcript: redact.AlreadyRedacted([]byte("initial transcript")),
 51			Prompts:    []string{"do the thing"}, FilesTouched: []string{"a.go"},
 52			AuthorName: "Test", AuthorEmail: "test@example.com",
 53		}))
 54		require.NoError(t, stores.Persistent.Write(ctx, ReservedSession{
 55			CheckpointID: reservedCID, SessionID: "reserved-session", Strategy: "manual-commit",
 56			Transcript: redact.AlreadyRedacted([]byte("reserved transcript")),
 57			AuthorName: "Test", AuthorEmail: "test@example.com",
 58		}))
 59		require.NoError(t, stores.Persistent.Write(ctx, BatchSessions{
 60			CheckpointID: batchCID,
 61			Sessions: []ReservedSession{
 62				{CheckpointID: batchCID, SessionID: "batch-b", Strategy: "manual-commit"},
 63				{CheckpointID: batchCID, SessionID: "batch-a", Strategy: "manual-commit"},
 64			},
 65			AuthorName: "Test", AuthorEmail: "test@example.com",
 66		}))
 67		require.NoError(t, stores.Persistent.Write(ctx, SessionTranscript{
 68			CheckpointID: cid, SessionID: sessionID,
 69			Transcript: redact.AlreadyRedacted([]byte("final transcript")),
 70			Prompts:    []string{"do the thing"},
 71		}))
 72		require.NoError(t, stores.Persistent.Write(ctx, SessionSummary{
 73			CheckpointID: cid, Summary: &Summary{Intent: "intent-x", Outcome: "outcome-y"},
 74		}))
 75		require.NoError(t, stores.Persistent.Write(ctx, CheckpointAttribution{
 76			CheckpointID: cid, Attribution: &Attribution{AgentLines: 7, AgentPercentage: 70},
 77		}))
 78	
 79		// Reads resolve from the git-refs primary.
 80		t.Run("git-refs primary", func(t *testing.T) {
 81			assertSeamVariants(t, stores.Persistent, cid, reservedCID, batchCID)
 82			// The primary is the per-checkpoint-ref store, not a fan-out of nothing.
 83			_, err := repo.Reference(mustRefName(t, cid), true)
 84			assert.NoError(t, err, "primary should have written the per-checkpoint ref")
 85		})
