 91		})
 92	
 93		// Reads must be served by the git-refs primary, not the mirror: after the
 94		// mirror's v1 branch is deleted, the composed store still reads everything.
 95		t.Run("reads resolve from primary", func(t *testing.T) {
 96			require.NoError(t, repo.Storer.RemoveReference(v1BranchRef()))
