137	func writeMirrorSettings(t *testing.T, repoDir, mirrorDir string) {
138		t.Helper()
139		// json-encode the path so separators / spaces are escaped correctly.
140		encodedPath, err := json.Marshal(mirrorDir)
141		require.NoError(t, err)
142		body := `{"enabled": true, "checkpoints": {"primary": {"type": "git-branch"}, "mirrors": [{"type": "fs", "config": {"path": ` +
