149	// spliceCheckpointSubtree installs a prebuilt checkpoint subtree at the shard
150	// location in the v1 root tree using O(depth) tree surgery, returning the new
151	// root tree hash. The v1 branch always shards on the first two ID characters.
152	func (s *GitStore) spliceCheckpointSubtree(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, checkpointSubtree plumbing.Hash) (plumbing.Hash, error) {
153		shardPrefix := string(checkpointID[:2])
154		shardSuffix := string(checkpointID[2:])
155		return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
156			{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointSubtree},
157		}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
158	}
