198	// applySummaryBackfill rewrites the requested session's summary on the checkpoint's
199	// current subtree, returning the new subtree hash and that session's ID (for the
200	// commit message). Returns ErrCheckpointNotFound when the checkpoint has no root
201	// summary.
202	func (s *treeWriter) applySummaryBackfill(ctx context.Context, existing *object.Tree, basePath, sessionID string, summary *Summary) (plumbing.Hash, string, error) {
203		entries, err := s.flattenExisting(existing, basePath)
204		if err != nil {
205			return plumbing.ZeroHash, "", err
206		}
207	
208		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
209		entry, exists := entries[rootMetadataPath]
210		if !exists {
211			return plumbing.ZeroHash, "", ErrCheckpointNotFound
212		}
213	
214		checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
215		if err != nil {
216			return plumbing.ZeroHash, "", fmt.Errorf("failed to read checkpoint summary: %w", err)
217		}
218	
219		targetIndex := len(checkpointSummary.Sessions) - 1
220		if sessionID != "" {
221			var findErr error
222			targetIndex, findErr = s.findSessionIndexByID(basePath, entries, checkpointSummary, sessionID)
223			if findErr != nil {
224				return plumbing.ZeroHash, "", findErr
225			}
226		}
227		sessionMetadataPath := checkpointSubtreePath(basePath, strconv.Itoa(targetIndex), paths.MetadataFileName)
228		sessionEntry, exists := entries[sessionMetadataPath]
229		if !exists {
230			return plumbing.ZeroHash, "", fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
300			sessionIndex = len(checkpointSummary.Sessions) - 1
301			logging.Debug(ctx, "backfillTranscript: session ID not found, falling back to latest",
302				slog.String("session_id", opts.SessionID),
303				slog.String("checkpoint_id", string(opts.CheckpointID)),
304				slog.Int("fallback_index", sessionIndex),
305			)
306			metaPath := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex), paths.MetadataFileName)
307			if metaEntry, metaExists := entries[metaPath]; metaExists {
308				sessionMeta, _ = s.readMetadataFromBlob(metaEntry.Hash) //nolint:errcheck // best-effort; nil meta means start 0
309			}
310		}
311	
312		sessionDir := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex))
313	
314		// Replace transcript (full replace, not append).
315		// Transcript is pre-redacted by the caller (enforced by RedactedBytes type).
316		if opts.Transcript.Len() > 0 {
317			agentType := opts.Agent
318			startLine := 0
319			if sessionMeta != nil {
320				startLine = sessionMeta.GetTranscriptStart()
321				if agentType == "" {
322					agentType = sessionMeta.Agent
323				}
324			}
325			rewrote, err := s.replaceTranscript(ctx, opts.Transcript, agentType, startLine, opts.PrecomputedBlobs, sessionDir, entries)
326			if err != nil {
327				return plumbing.ZeroHash, fmt.Errorf("failed to replace transcript: %w", err)
328			}
329	
330			// Only touch assets and the root pointers when the transcript was actually
331			// rewritten. If replaceTranscript short-circuited (identical content), the
332			// stored transcript, compact, and assets are all unchanged and already
333			// consistent — clearing/rewriting assets here would strip the blobs a
334			// still-present placeholder depends on, leaving a dangling placeholder.
335			if rewrote {
336				// Keep the externalized image assets consistent with the replaced
337				// transcript: write the new set (clearing any stale ones), so a finalize
338				// that re-externalizes matches its placeholders and one that produces an
339				// inline transcript leaves no orphaned blobs.
340				manifestPath, err := s.writeAssetsForBackfill(opts, sessionDir, entries)
341				if err != nil {
342					return plumbing.ZeroHash, fmt.Errorf("failed to write assets: %w", err)
343				}
344	
345				// Keep the root metadata.json compact_transcript and assets_manifest
346				// pointers consistent with the finalized tree. replaceTranscript may have
347				// written transcript.jsonl that the initial write lacked (e.g. compaction
348				// was skipped then and succeeds now), so re-derive both pointers from the
349				// tree and rewrite the root summary once when either changed.
350				compactPath := ""
351				if _, ok := entries[checkpointSubtreePath(sessionDir, paths.CompactTranscriptFileName)]; ok {
352					compactPath = "/" + checkpointSubtreePath(sessionDir, paths.CompactTranscriptFileName)
353				}
354				sess := &checkpointSummary.Sessions[sessionIndex]
355				if sess.CompactTranscript != compactPath || sess.AssetsManifest != manifestPath {
356					sess.CompactTranscript = compactPath
357					sess.AssetsManifest = manifestPath
358					summaryJSON, err := jsonutil.MarshalIndentWithNewline(checkpointSummary, "", "  ")
359					if err != nil {
360						return plumbing.ZeroHash, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
361					}
362					summaryHash, err := CreateBlobFromContent(s.repo, summaryJSON)
363					if err != nil {
364						return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
365					}
366					entries[rootMetadataPath] = object.TreeEntry{
367						Name: rootMetadataPath,
368						Mode: filemode.Regular,
369						Hash: summaryHash,
370					}
371				}
372			}
373		}
374	
375		// Replace prompts with regex-only-redacted content.
376		if len(opts.Prompts) > 0 {
377			promptContent := RedactedJoinedPrompts(opts.Prompts)
378			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
379			if err != nil {
380				return plumbing.ZeroHash, fmt.Errorf("failed to create prompt blob: %w", err)
381			}
382			promptPath := checkpointSubtreePath(sessionDir, paths.PromptFileName)
383			entries[promptPath] = object.TreeEntry{
384				Name: promptPath,
385				Mode: filemode.Regular,
386				Hash: blobHash,
387			}
388		}
389	
390		if len(opts.SkillEvents) > 0 {
391			if err := s.replaceSkillEvents(opts.SkillEvents, sessionDir, entries); err != nil {
392				return plumbing.ZeroHash, fmt.Errorf("failed to replace skill events: %w", err)
393			}
394		}
395	
396		return s.buildCheckpointSubtree(ctx, entries, basePath)
397	}
