  1	package checkpoint
  2	
  3	import (
  4		"bufio"
  5		"bytes"
  6		"context"
  7		"encoding/json"
  8		"fmt"
  9		"os"
 10		"path/filepath"
 11	
 12		"github.com/go-git/go-git/v6"
 13		"github.com/go-git/go-git/v6/plumbing"
 14	
 15		"github.com/entireio/cli/cmd/entire/cli/internal/flock"
 16	)
 17	
 18	// Push-discovery queue file names, kept in the git common dir so every worktree
 19	// sharing the object store enqueues into one queue. The git-refs backend cannot
 20	// push every local checkpoint ref at pre-push time (reads fetch refs too, and
 21	// deleting them after push would hurt local workflows), so each write records
 22	// the ref it touched here and pre-push drains + batch-pushes exactly those.
 23	const (
 24		pushQueueFileName = "entire-checkpoint-push-queue.jsonl"
 25		pushQueueLockName = "entire-checkpoint-push-queue.lock"
 26	)
 27	
 28	// pushQueueEntry is one JSONL record: a checkpoint ref awaiting push.
 29	type pushQueueEntry struct {
 30		Ref string `json:"ref"`
 31	}
 32	
 33	// PushQueue is a flock-protected JSONL list of checkpoint refs awaiting push,
 34	// stored in the git common dir. Entries are removed only after a confirmed push
 35	// (Remove), so an interrupted or failed push leaves them for the next pre-push.
 36	// Duplicates are tolerated on disk and collapsed by Drain.
 37	type PushQueue struct {
 38		dir string
 39	}
 40	
 41	// NewPushQueue returns the push queue rooted at gitCommonDir.
 42	func NewPushQueue(gitCommonDir string) *PushQueue {
 43		return &PushQueue{dir: gitCommonDir}
 44	}
 45	
 46	// PushQueueForRepo resolves the git common dir for repo and returns its queue.
 47	func PushQueueForRepo(ctx context.Context, repo *git.Repository) (*PushQueue, error) {
 48		dir, err := resolveGitCommonDir(ctx, repo)
 49		if err != nil {
 50			return nil, err
 51		}
 52		return NewPushQueue(dir), nil
 53	}
 54	
 55	func (q *PushQueue) queuePath() string { return filepath.Join(q.dir, pushQueueFileName) }
 56	func (q *PushQueue) lockPath() string  { return filepath.Join(q.dir, pushQueueLockName) }
 57	
 58	// Enqueue appends a ref to the queue. It is safe to enqueue a ref already
 59	// present (or already pushed): Drain collapses duplicates and the batch push is
 60	// idempotent. Enqueue takes the lock so concurrent writers never interleave a
 61	// partial line.
 62	func (q *PushQueue) Enqueue(ref plumbing.ReferenceName) error {
 63		release, err := flock.Acquire(q.lockPath())
 64		if err != nil {
 65			return fmt.Errorf("lock push queue: %w", err)
 66		}
 67		defer release()
 68	
 69		line, err := json.Marshal(pushQueueEntry{Ref: ref.String()})
 70		if err != nil {
 71			return fmt.Errorf("encode push queue entry: %w", err)
 72		}
 73		f, err := os.OpenFile(q.queuePath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
 74		if err != nil {
 75			return fmt.Errorf("open push queue: %w", err)
 76		}
 77		defer f.Close()
 78		if _, err := f.Write(append(line, '\n')); err != nil {
 79			return fmt.Errorf("append push queue entry: %w", err)
 80		}
 81		return nil
 82	}
 83	
 84	// Drain returns the de-duplicated refs currently queued, in first-seen order. It
 85	// does NOT remove them; call Remove after a confirmed push so a failed push
 86	// retries next time. A missing queue file yields no refs.
 87	//
 88	// It compacts the file in place: when the on-disk queue held redundant lines
 89	// (duplicate enqueues of the same ref, or malformed/blank lines), Drain rewrites
 90	// it to the de-duplicated set. Enqueue only ever appends, so without this the
 91	// file would grow unboundedly between the Removes that are otherwise the sole
 92	// compaction point (e.g. a long-lived session that keeps re-enqueuing the same
 93	// checkpoint ref but never pushes).
 94	func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
 95		release, err := flock.Acquire(q.lockPath())
 96		if err != nil {
 97			return nil, fmt.Errorf("lock push queue: %w", err)
 98		}
 99		defer release()
100	
101		refs, rawLines, err := q.readLocked()
102		if err != nil {
103			return nil, err
104		}
105		if rawLines > len(refs) {
106			if err := q.rewriteLocked(refs); err != nil {
107				return nil, err
108			}
109		}
110		return refs, nil
111	}
112	
113	// Peek returns the de-duplicated refs currently queued, in first-seen order,
114	// without mutating the queue file. Read-only counterpart to Drain (which
115	// compacts redundant lines in place) — for counters/status displays that must
116	// observe the queue without owning a push. A missing queue file yields no refs.
117	func (q *PushQueue) Peek() ([]plumbing.ReferenceName, error) {
118		release, err := flock.Acquire(q.lockPath())
119		if err != nil {
120			return nil, fmt.Errorf("lock push queue: %w", err)
121		}
122		defer release()
123	
124		refs, _, err := q.readLocked()
125		return refs, err
126	}
127	
128	// Remove deletes the given refs from the queue, preserving any entries appended
129	// after a Drain (e.g. a write that landed during the push). Called after a
130	// confirmed push.
131	func (q *PushQueue) Remove(refs []plumbing.ReferenceName) error {
132		if len(refs) == 0 {
133			return nil
134		}
135		release, err := flock.Acquire(q.lockPath())
136		if err != nil {
137			return fmt.Errorf("lock push queue: %w", err)
138		}
139		defer release()
140	
141		current, _, err := q.readLocked()
142		if err != nil {
143			return err
144		}
145		removed := make(map[string]struct{}, len(refs))
146		for _, r := range refs {
147			removed[r.String()] = struct{}{}
148		}
149		kept := make([]plumbing.ReferenceName, 0, len(current))
150		for _, r := range current {
151			if _, drop := removed[r.String()]; drop {
152				continue
153			}
154			kept = append(kept, r)
155		}
156		return q.rewriteLocked(kept)
157	}
158	
159	// rewriteLocked replaces the queue file with exactly refs (de-duplicated, one
160	// line each), or removes the file when refs is empty so a clean repo has no
161	// stray queue. The caller must hold the lock. The write is atomic (temp file +
162	// rename) so a concurrent reader never sees a half-written queue.
163	func (q *PushQueue) rewriteLocked(refs []plumbing.ReferenceName) error {
164		if len(refs) == 0 {
165			if err := os.Remove(q.queuePath()); err != nil && !os.IsNotExist(err) {
166				return fmt.Errorf("remove empty push queue: %w", err)
167			}
168			return nil
169		}
170		var buf bytes.Buffer
171		for _, r := range refs {
172			line, err := json.Marshal(pushQueueEntry{Ref: r.String()})
173			if err != nil {
174				return fmt.Errorf("encode push queue entry: %w", err)
175			}
176			buf.Write(line)
177			buf.WriteByte('\n')
178		}
179		if err := writeFileAtomicInDir(q.dir, q.queuePath(), buf.Bytes()); err != nil {
180			return fmt.Errorf("rewrite push queue: %w", err)
181		}
182		return nil
183	}
184	
185	// readLocked parses the queue file into de-duplicated refs, preserving first-seen
186	// order. The caller must hold the lock. Malformed lines are skipped rather than
187	// failing the whole drain — a single bad record must not strand every queued ref.
188	//
189	// rawLines is the number of non-empty lines seen (including duplicates and
190	// malformed records), so callers can detect when the file holds more than the
191	// de-duplicated set and is worth compacting: rawLines > len(refs) exactly when
192	// there were redundant lines.
193	func (q *PushQueue) readLocked() (refs []plumbing.ReferenceName, rawLines int, err error) {
194		f, err := os.Open(q.queuePath())
195		if err != nil {
196			if os.IsNotExist(err) {
197				return nil, 0, nil
198			}
199			return nil, 0, fmt.Errorf("open push queue: %w", err)
200		}
201		defer f.Close()
202	
203		seen := make(map[string]struct{})
204		scanner := bufio.NewScanner(f)
205		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
206		for scanner.Scan() {
207			line := bytes.TrimSpace(scanner.Bytes())
208			if len(line) == 0 {
209				continue
210			}
211			rawLines++
212			var entry pushQueueEntry
213			if err := json.Unmarshal(line, &entry); err != nil || entry.Ref == "" {
214				continue
215			}
216			if _, dup := seen[entry.Ref]; dup {
217				continue
218			}
219			seen[entry.Ref] = struct{}{}
220			refs = append(refs, plumbing.ReferenceName(entry.Ref))
221		}
222		if err := scanner.Err(); err != nil {
223			return nil, 0, fmt.Errorf("read push queue: %w", err)
224		}
225		return refs, rawLines, nil
226	}
227	
228	// writeFileAtomicInDir writes data to a temp file in dir and renames it over
229	// path, so a reader (under the lock) never sees a half-written queue.
230	func writeFileAtomicInDir(dir, path string, data []byte) error {
231		tmp, err := os.CreateTemp(dir, pushQueueFileName+".*")
232		if err != nil {
233			return fmt.Errorf("create temp push queue: %w", err)
234		}
235		tmpName := tmp.Name()
236		defer os.Remove(tmpName)
237		if _, err := tmp.Write(data); err != nil {
238			_ = tmp.Close()
239			return fmt.Errorf("write temp push queue: %w", err)
240		}
241		if err := tmp.Close(); err != nil {
242			return fmt.Errorf("close temp push queue: %w", err)
243		}
244		if err := os.Rename(tmpName, path); err != nil {
245			return fmt.Errorf("rename temp push queue: %w", err)
246		}
247		return nil
248	}

