234		}
235		tmpName := tmp.Name()
236		defer os.Remove(tmpName)
237		if _, err := tmp.Write(data); err != nil {
238			_ = tmp.Close()
239			return fmt.Errorf("write temp push queue: %w", err)
240		}
241		if err := tmp.Close(); err != nil {
242			return fmt.Errorf("close temp push queue: %w", err)
243		}
244		if err := os.Rename(tmpName, path); err != nil {
245			return fmt.Errorf("rename temp push queue: %w", err)
246		}
247		return nil
248	}

