 726	// ParseShadowBranchName extracts the commit prefix and worktree hash from a shadow branch name.
 727	// Input format: "entire/<commit[:7]>-<worktreeHash[:6]>"
 728	// Returns (commitPrefix, worktreeHash, ok). Returns ("", "", false) if not a valid shadow branch.
 729	func ParseShadowBranchName(branchName string) (commitPrefix, worktreeHash string, ok bool) {
 730		if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
 731			return "", "", false
 732		}
 733		suffix := strings.TrimPrefix(branchName, ShadowBranchPrefix)
 734	
 735		// Find the last dash - everything before is commit prefix, after is worktree hash
 736		lastDash := strings.LastIndex(suffix, "-")
 737		if lastDash == -1 || lastDash == 0 || lastDash == len(suffix)-1 {
 738			// No dash, or dash at start/end - invalid format
 739			// Could be old format "entire/<commit[:7]>" without worktree hash
 740			return suffix, "", true // Return as commit prefix with empty worktree hash
 741		}
 742	
 743		return suffix[:lastDash], suffix[lastDash+1:], true
 744	}
